"""
backend/app/adaptive_data/models.py — Pydantic v2 Domain Models for Adaptive Data Engine.

Defines schemas for CleaningReport, ValidationReport, BalanceReport, OptimizationPlan,
EnrichmentReport, AdaptiveDataReport, and TrainingReadyDataset.
"""

from datetime import datetime
from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field, ConfigDict

from app.dataset_generator.models import ScientificReasoningRecord


class CleaningReport(BaseModel):
    """Report generated by Agent 1: Dataset Cleaner."""
    duplicates_removed: int = Field(..., ge=0, description="Count of duplicate records removed")
    invalid_samples_removed: int = Field(..., ge=0, description="Count of invalid/corrupted records removed")
    repaired_samples: int = Field(..., ge=0, description="Count of records repaired during cleaning")
    rejected_samples: int = Field(..., ge=0, description="Count of irrecoverable rejected records")
    initial_sample_count: int = Field(..., ge=0, description="Sample count prior to cleaning")
    cleaned_sample_count: int = Field(..., ge=0, description="Sample count after cleaning")
    cleaning_score: float = Field(..., ge=0.0, le=100.0, description="Normalized cleaning quality score [0..100]")


class ValidationIssue(BaseModel):
    """Individual scientific validation flaw detected by Agent 2: Scientific Validator."""
    record_id: str = Field(..., description="ID of record containing the validation issue")
    issue_type: str = Field(..., description="Type of flaw (e.g. MISSING_FIELD, WEAK_REASONING, LOGICAL_FLAW)")
    severity: str = Field(..., description="Issue severity: CRITICAL, HIGH, MEDIUM, LOW")
    description: str = Field(..., description="Explanation of why this reasoning chain step failed validation")


class ValidationReport(BaseModel):
    """Report generated by Agent 2: Scientific Validator."""
    valid_sample_count: int = Field(..., ge=0, description="Count of scientifically valid samples")
    invalid_sample_count: int = Field(..., ge=0, description="Count of samples with validation flaws")
    weak_chain_count: int = Field(..., ge=0, description="Count of samples with weak reasoning chains")
    logical_flaw_count: int = Field(..., ge=0, description="Count of critical logical flaws")
    validation_score: float = Field(..., ge=0.0, le=100.0, description="Normalized scientific validation score [0..100]")
    validation_issues: List[ValidationIssue] = Field(default_factory=list, description="Detailed list of validation issues")


class TargetSampleRecommendation(BaseModel):
    """Target sample generation recommendation generated by Agent 3: Dataset Balancer."""
    target_domain: str = Field(..., description="Scientific domain requiring additional samples")
    target_difficulty: str = Field(..., description="Difficulty level requiring samples")
    recommended_count: int = Field(..., ge=1, description="Recommended number of samples to generate")
    reason: str = Field(..., description="Justification based on domain/difficulty distribution imbalance")


class BalanceReport(BaseModel):
    """Report generated by Agent 3: Dataset Balancer."""
    domain_distribution: Dict[str, int] = Field(default_factory=dict, description="Current sample count per domain")
    difficulty_distribution: Dict[str, int] = Field(default_factory=dict, description="Current sample count per difficulty")
    experiment_type_distribution: Dict[str, int] = Field(default_factory=dict, description="Current sample count per experiment type")
    imbalance_detected: bool = Field(..., description="Flag indicating if severe distribution imbalance was detected")
    balance_score: float = Field(..., ge=0.0, le=100.0, description="Normalized dataset balance score [0..100]")
    target_sample_recommendations: List[TargetSampleRecommendation] = Field(default_factory=list, description="Target recommendations")


class OptimizationRecommendationItem(BaseModel):
    """Individual optimization action item generated by Agent 4: Dataset Optimizer."""
    recommendation_id: str = Field(..., description="Unique recommendation ID")
    action_type: str = Field(..., description="Type of optimization (e.g. INCREASE_COVERAGE, EXPAND_DIVERSITY)")
    reason: str = Field(..., description="Justification connecting back to Dataset Intelligence report")
    priority: int = Field(..., ge=1, description="1-indexed priority ranking")
    expected_improvement: float = Field(..., ge=0.0, description="Expected delta health gain (+points)")
    estimated_sample_count: int = Field(..., ge=1, description="Estimated new sample count")


class OptimizationPlan(BaseModel):
    """Report generated by Agent 4: Dataset Optimizer."""
    optimization_recommendations: List[OptimizationRecommendationItem] = Field(default_factory=list, description="Prioritized recommendations")
    expected_health_gain: float = Field(..., ge=0.0, description="Total projected health score gain (+points)")
    target_domain_allocations: Dict[str, int] = Field(default_factory=dict, description="Allocated sample counts per domain")
    optimizer_score: float = Field(..., ge=0.0, le=100.0, description="Normalized optimization potential score [0..100]")


class EnrichmentReport(BaseModel):
    """Report generated by Agent 5: Dataset Enricher."""
    enriched_sample_count: int = Field(..., ge=0, description="Count of samples successfully enriched")
    context_enhanced_count: int = Field(..., ge=0, description="Count of samples with enhanced scientific context")
    hypotheses_strengthened_count: int = Field(..., ge=0, description="Count of samples with strengthened alternative hypotheses")
    metrics_improved_count: int = Field(..., ge=0, description="Count of samples with refined evaluation metrics")
    enrichment_score: float = Field(..., ge=0.0, le=100.0, description="Normalized enrichment quality score [0..100]")


class AdaptiveDataReport(BaseModel):
    """Overall report generated by Agent 6: Adaptive Scorer."""
    cleaning_score: float = Field(..., ge=0.0, le=100.0, description="Score from Agent 1: Dataset Cleaner")
    validation_score: float = Field(..., ge=0.0, le=100.0, description="Score from Agent 2: Scientific Validator")
    coverage_score: float = Field(..., ge=0.0, le=100.0, description="Reasoning & domain coverage score")
    balance_score: float = Field(..., ge=0.0, le=100.0, description="Score from Agent 3: Dataset Balancer")
    optimization_score: float = Field(..., ge=0.0, le=100.0, description="Score from Agent 4: Dataset Optimizer")
    enrichment_score: float = Field(..., ge=0.0, le=100.0, description="Score from Agent 5: Dataset Enricher")
    overall_adaptive_score: float = Field(..., ge=0.0, le=100.0, description="Weighted composite adaptive quality score [0..100]")
    training_readiness: bool = Field(..., description="Flag indicating if dataset meets training readiness criteria")
    generated_at: datetime = Field(default_factory=datetime.utcnow, description="Scoring timestamp")


class TrainingReadyDataset(BaseModel):
    """
    Final Output Object returned by AdaptiveDataPipeline.
    
    Contains the optimized, cleaned, enriched records alongside full execution reports.
    """
    model_config = ConfigDict(arbitrary_types_allowed=True)

    dataset_version: str = Field(..., description="Canonical dataset version identifier (e.g. v2.1-adaptive)")
    adaptive_score: float = Field(..., ge=0.0, le=100.0, description="Overall composite adaptive score")
    training_ready: bool = Field(..., description="Boolean flag: True if ready for AutoScientist / fine-tuning")
    cleaned_records: List[ScientificReasoningRecord] = Field(default_factory=list, description="Optimized, validated, and enriched records")
    cleaning_summary: CleaningReport = Field(..., description="Report from Agent 1")
    validation_summary: ValidationReport = Field(..., description="Report from Agent 2")
    balance_summary: BalanceReport = Field(..., description="Report from Agent 3")
    optimization_summary: OptimizationPlan = Field(..., description="Report from Agent 4")
    enrichment_summary: EnrichmentReport = Field(..., description="Report from Agent 5")
    adaptive_report: AdaptiveDataReport = Field(..., description="Report from Agent 6")
    recommendations: List[str] = Field(default_factory=list, description="High-level human readable recommendations")
    created_at: datetime = Field(default_factory=datetime.utcnow, description="Pipeline completion timestamp")
